class UserMessage:
    """Represents a message received from the user."""

    def __init__(self, text):
        self.text = text


class AgentResponse:
    """Represents a response generated by the assistant."""

    def __init__(self, text, intent="general"):
        self.text = text
        self.intent = intent


class ToolResult:
    """Represents the result returned by an AbeyYaar tool."""

    def __init__(self, success, message, data=None):
        self.success = success
        self.message = message
        self.data = data